//go:build acceptance

package acceptance

import (
	"encoding/json"
	"net/http"
	"slices"
	"testing"
)

// The personal account, end to end (task 7.3).

// domainRef is as much of a created domain as these tests address it by. The
// alias label is the interesting field: it is where the challenge value becomes
// answerable, and it is generated by the service rather than chosen.
type domainRef struct {
	ID            string `json:"id"`
	Name          string `json:"name"`
	ChallengeName string `json:"challengeName"`
	AliasLabel    string `json:"aliasLabel"`
}

// TestThePersonalAccountArc walks what a new user actually does: sign in, land
// at the picker with somewhere to work already in it, choose it, build one
// project's worth of inventory, and publish a challenge for it.
//
// This is the arc that could not be walked before. Every step of it either did
// not exist (the personal account, the picker as the front door) or was done for
// the user by the edition being removed (the selection). Nothing here is
// fixtured except the sign-in: the account is materialized by signing in and
// everything else goes through the service's own API.
//
// read-only-user is used ON PURPOSE. In the seeded team account that person may
// not create a domain — TestRoleEnforcementThroughTheManagementAPI asserts
// exactly that — and here they create a whole inventory, because in their own
// account they are the owner and hold its one unrestricted role. Authority is a
// property of a person IN an account, and using the most-restricted user is what
// makes that visible rather than merely true (design C10).
func TestThePersonalAccountArc(t *testing.T) {
	s := mustSignIn(t, readOnlyUser, devPassword)

	// 1. The picker, with the account nobody created already in it.
	personal := s.personalAccount(t)
	if personal.Selected {
		t.Fatalf("the personal account is already selected; signing in must leave the "+
			"choice to the user (design P19). Picker: %v", slugs(s.accounts(t)))
	}

	// 2. Choosing it, and the authority that appears with the choice.
	s.selectInto(t, personal)
	me := s.me(t)
	if me.SelectedAccountID == nil || *me.SelectedAccountID != personal.ID {
		t.Fatalf("after selecting %s, /me reports %v", personal.Slug, me.SelectedAccountID)
	}
	if !slices.Contains(me.Roles, "OWNER") {
		t.Fatalf("in their own account %s holds roles %v, want OWNER — a personal account "+
			"has exactly one role and its owner holds it (store.PersonalAccountRole)",
			readOnlyUser, me.Roles)
	}

	// 3. A project. This is the step that proves the account is a real tenant
	// and not a label: everything below carries its account_id.
	slug := unique("acc-personal")
	var project projectRef
	if err := s.json(http.MethodPost, s.acct("/projects"),
		map[string]string{"slug": slug, "name": "Acceptance (personal)"},
		http.StatusCreated, &project); err != nil {
		t.Fatalf("creating a project in %s's personal account: %v", readOnlyUser, err)
	}
	t.Cleanup(func() {
		// Deleting the project takes the load balancer, the domain and the alias
		// with it, which also keeps the five-project quota clear for a stack
		// that is kept between runs (design C13).
		_, _, _ = s.do(http.MethodDelete, s.acct("/projects/"+project.ID), nil)
	})

	var lb lbRef
	if err := s.json(http.MethodPost, s.acct("/projects/"+project.ID+"/loadbalancers"),
		map[string]string{"slug": "prod", "name": "Acceptance (personal)"},
		http.StatusCreated, &lb); err != nil {
		t.Fatalf("creating a load balancer: %v", err)
	}
	// Under example.com because that is the zone the fake internet is
	// authoritative for, and a domain that resolves nowhere can never activate
	// (domain-activation A1). The name stays unique per run.
	var domain domainRef
	if err := s.json(http.MethodPost, s.acct("/loadbalancers/"+lb.ID+"/domains"),
		map[string]string{"name": slug + ".example.com"}, http.StatusCreated, &domain); err != nil {
		t.Fatalf("creating a domain: %v", err)
	}

	// 4. Roles and members are ABSENT here rather than empty (design C9, task
	// 3.3), and the grant model is not — the key below is minted in the same
	// account whose roster was just refused. The two assertions sit together
	// because deleting the roles machinery along with the roles screen is the
	// mistake C9 names, and this is where it would show.
	if status, body, err := s.do(http.MethodGet, s.acct("/roles"), nil); err != nil {
		t.Fatalf("listing roles in a personal account: %v", err)
	} else if status != http.StatusConflict {
		t.Errorf("GET /roles in a personal account: got %d, want 409 — there CANNOT be roles "+
			"here, which is a different sentence from there being none yet: %s", status, body)
	}
	if status, body, err := s.do(http.MethodPost, s.acct("/members"),
		map[string]any{"subject": "nobody", "roleId": personal.ID}); err != nil {
		t.Fatalf("adding a member to a personal account: %v", err)
	} else if status != http.StatusConflict {
		t.Errorf("POST /members in a personal account: got %d, want 409: %s", status, body)
	}

	// 5. Publishing a challenge for it — the thing the whole service is for,
	// done in an account that came into existence by somebody signing in.
	key := mintKey(t, s, lb.ID, "acceptance: personal account", nil)
	const value = "acceptance-personal-account-value"
	alias := aliasNameFor(domain.AliasLabel)

	// 5a. And it is refused first, because nobody has published the delegation
	// yet (domain-activation A1, A4, task 5.6).
	//
	// This is the one place the gate can be proven distinguishable rather than
	// merely present: the account is personal, so it is funded by definition and
	// a 402 is impossible; nothing has suspended it, so a 403 is impossible; the
	// key was minted on this very load balancer, so a 403 for authority is
	// impossible; and the domain exists, so a 404 is impossible. The only thing
	// wrong with this request is the state of the domain, and 409 is the only
	// answer that says so. The very next lines fix exactly that one thing and
	// the same call succeeds.
	if got := present(t, "/present", key.Key.Identifier, key.Secret, domain.ChallengeName, value, nil); got != http.StatusConflict {
		t.Fatalf("publishing for %s before its delegation exists: got %d, want 409 — a domain "+
			"whose CNAME has never been seen is offline, and it is refused as a state "+
			"problem the customer can fix (409), not as money (402), a suspension (403) or "+
			"an unknown name (404)", domain.Name, got)
	}
	if vals, _, err := txtValues(serviceDNS, alias); err != nil {
		t.Fatalf("querying %s: %v", alias, err)
	} else if len(vals) != 0 {
		t.Errorf("%s answers %v after a refused publish; a 409 must leave nothing behind", alias, vals)
	}

	// 5b. The customer publishes the delegation, and we look. Now it works.
	onboardDomain(t, s, lb.ID, domain)

	if got := present(t, "/present", key.Key.Identifier, key.Secret, domain.ChallengeName, value, nil); got != http.StatusOK {
		t.Fatalf("publishing a challenge for %s: got %d, want 200", domain.Name, got)
	}
	vals, _, err := txtValues(serviceDNS, alias)
	if err != nil {
		t.Fatalf("querying %s: %v", alias, err)
	}
	if !slices.Contains(vals, value) {
		t.Errorf("%s answers %v, which does not include the value just published for %s",
			alias, vals, domain.Name)
	}
	if got := present(t, "/cleanup", key.Key.Identifier, key.Secret, domain.ChallengeName, value, nil); got != http.StatusOK {
		t.Fatalf("withdrawing the challenge: got %d, want 200", got)
	}
	if vals, _, err = txtValues(serviceDNS, alias); err != nil {
		t.Fatalf("querying %s after cleanup: %v", alias, err)
	}
	if len(vals) != 0 {
		t.Errorf("%s still answers %v after cleanup", alias, vals)
	}
}

// TestThePersonalAccountRunsOutOfRoomRatherThanOutOfPermission is design C13's
// distinction, through the API.
//
// A quota and a permission are different questions with different remedies:
// "there is no room, delete one or move to a team account" against "ask whoever
// can grant it". Answering both with 403 produces one message that is wrong for
// whichever case it was not written for — and in a personal account the wrong
// one is especially wrong, because there is nobody to ask.
//
// The NUMBER is deliberately not asserted. It is configuration
// (ACME_PROJECT_QUOTA, task 3.5a) and a deployment may set it to six; what this
// asserts is that there IS a ceiling and what hitting it looks like.
func TestThePersonalAccountRunsOutOfRoomRatherThanOutOfPermission(t *testing.T) {
	s := mustSignIn(t, keyRotationUser, devPassword)
	s.selectInto(t, s.personalAccount(t))

	const ceiling = 25 // far above any sane quota; a runaway loop is a failure, not a hang
	var refusal int
	var body []byte
	for i := 0; i < ceiling; i++ {
		var project projectRef
		status, raw, err := s.do(http.MethodPost, s.acct("/projects"),
			map[string]string{"slug": unique("acc-quota"), "name": "Acceptance (quota)"})
		if err != nil {
			t.Fatalf("creating project %d: %v", i, err)
		}
		if status != http.StatusCreated {
			refusal, body = status, raw
			break
		}
		if err := json.Unmarshal(raw, &project); err != nil {
			t.Fatalf("decoding the created project: %v", err)
		}
		t.Cleanup(func() {
			_, _, _ = s.do(http.MethodDelete, s.acct("/projects/"+project.ID), nil)
		})
	}
	switch refusal {
	case 0:
		t.Fatalf("a personal account accepted %d projects without a refusal; the quota of "+
			"design C13 is not being applied", ceiling)
	case http.StatusConflict:
		// What it must be: there is no room.
	case http.StatusForbidden:
		t.Fatalf("the quota was refused as a PERMISSION (403): %s — in a personal account "+
			"there is nobody to ask for a grant, so the remedy that message points at does "+
			"not exist (design C13, task 3.5b)", body)
	default:
		t.Fatalf("creating one project too many: got %d, want 409: %s", refusal, body)
	}
}
